def issort_list(lst):
    """Check if the list is sorted in ascending order."""
    # Handle empty or single-element lists (they are considered sorted)
    if len(lst) <= 1:
        return True

    for i in range(1, len(lst)):
        if lst[i] < lst[i - 1]:
            return False
    return True


